import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: number
}

// In-memory store so the example runs without a database. In a real app
// this would be a database query. New posts created by the Server Action
// are appended here, and the 'posts' cache tag is invalidated so the list
// re-fetches fresh data instead of serving stale cached content.
const store: Post[] = [
  {
    id: '1',
    title: 'Welcome',
    content: 'This is the first post.',
    createdAt: Date.now(),
  },
]

export async function createPostInStore(title: string, content: string) {
  const post: Post = {
    id: String(store.length + 1),
    title,
    content,
    createdAt: Date.now(),
  }
  store.push(post)
  return post
}

// Cached posts list. The 'use cache' directive makes this cacheable, and
// cacheTag('posts') associates it with the 'posts' tag so it can be
// invalidated on-demand from the Server Action.
export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return store
}

