import { updateTag } from 'next/cache'
import { createPostInStore } from './data'

// Server Action that creates a new post and invalidates the 'posts' cache tag.
//
// We use updateTag (not revalidateTag) because the requirement is that the
// user must NOT see stale cached data after creating a post: the next page
// load must wait for fresh data to be fetched rather than serving old cached
// content. Per the Next.js docs, updateTag "immediately expires the cached
// data for the specified tag. The next request will wait to fetch fresh data
// rather than serving stale content from the cache." revalidateTag with the
// recommended 'max' profile uses stale-while-revalidate semantics and would
// serve stale content, which is exactly what we must avoid here.
//
// updateTag can only be called from within a Server Action, which this is.
export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    return { error: 'Title is required' }
  }

  await createPostInStore(title, content)

  // Immediately expire the 'posts' cache tag so the next read fetches fresh
  // data. This also triggers a re-render of the current route in the same
  // Server Action response, so the user sees the new post right away.
  updateTag('posts')

  return { error: null }
}
","path":"/workspace/app/actions.ts"}

